def stepMap (α δ : ℝ) (P : MLin 𝕜 X Y (d + 1)) : MLin 𝕜 X Y (d + 1) :=
  P + ((α : ℝ) : 𝕜) • (Rop (pick P δ).1 (pick P δ).2.1
    ((pick P δ).2.2.compContinuousMultilinearMap P)).smulRight (wvec P (pick P δ))

