def etaV (d : ℕ) (a : ℝ) (m : ℕ) : ℝ :=
  hConst (d + 1) * Real.sqrt (2 * ((7 * Kc (d + 1)) ^ (d + 1) * alpha a m)) +
    4 * (cPol (d + 1) + 1) * alpha a m

