def Rop (u : X) (f : StrongDual 𝕜 X) (a : MLin 𝕜 X 𝕜 n) : MLin 𝕜 X 𝕜 n :=
  symmetrize (∑ s : Finset (Fin n), ((betaW n s.card : ℝ) : 𝕜) •
    a.compContinuousLinearMap (fun i => if i ∈ s then ContinuousLinearMap.id 𝕜 X
      else f.smulRight u))

